package com.aistock.prediction.question;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import org.springframework.http.HttpStatus;import java.util.*;import java.time.*;import java.security.*;
public final class QuestionFacts {
 public static final String PROMPT="grounded-stock-question-v2",KNOWLEDGE="qa-knowledge-v1";
 public record Facts(Map<String,String> values,JsonNode context,String hash){}
 private QuestionFacts(){}
 public static Facts build(JsonNode saved,String question,String model,ObjectMapper m){try{String id=saved.path("analysisId").asText();UUID.fromString(id);Instant.parse(saved.path("createdAt").asText());String sourceHash=saved.path("contextHash").asText();if(!sourceHash.matches("[a-f0-9]{64}")||model==null||model.isBlank())throw invalid();var c=saved.path("context");String stock=c.path("instrumentId").asText();if(!stock.matches("(SH|SZ)[0-9]{6}")||!"RAW".equals(c.path("priceBasis").asText())||!"tech-v1".equals(c.path("formulaVersion").asText()))throw invalid();UUID.fromString(c.path("marketVersionId").asText());LocalDate from=LocalDate.parse(c.path("from").asText()),to=LocalDate.parse(c.path("to").asText());if(from.isAfter(to))throw invalid();var f=new TreeMap<String,String>();var allowed=new HashSet<>(List.of("STOCK","RANGE_FROM","RANGE_TO","AS_OF","CLOSE","MA5","MA10","MA20","MA5_STATE","MA10_STATE","MA20_STATE","DIF","DEA","MACD","MACD_STATE","RSI14","RSI_STATE","BASIS_LIMIT","FRESHNESS_LIMIT"));boolean pred=c.path("prediction").isObject();if(pred){UUID.fromString(c.path("prediction").path("predictionId").asText());allowed.addAll(List.of("PRED_ORIGIN_DATE","PRED_ORIGIN_CLOSE","PRED_TREND","PRED_RELATIVE_ORIGIN","PRED_VERIFICATION","PRED_LIMIT","PRED_CONTEXT_RELATION","PRED_METRICS"));for(int i=1;i<=5;i++){allowed.add("PRED_D"+i);allowed.add("PRED_P"+i);}}var source=c.path("facts");if(!source.isObject())throw invalid();for(String k:allowed){var v=source.path(k);if(v.isMissingNode())continue;if(!v.isTextual()||v.asText().isBlank()||v.asText().length()>2000)throw invalid();f.put(k,v.asText());}for(String k:List.of("STOCK","AS_OF","CLOSE","MA5_STATE","MACD_STATE","RSI_STATE","BASIS_LIMIT","FRESHNESS_LIMIT"))if(!f.containsKey(k))throw invalid();if(!stock.equals(f.get("STOCK")))throw invalid();LocalDate date=LocalDate.parse(f.get("AS_OF"));if(date.isBefore(from)||date.isAfter(to))throw invalid();if(pred){for(String k:List.of("PRED_ORIGIN_DATE","PRED_TREND","PRED_RELATIVE_ORIGIN","PRED_VERIFICATION","PRED_LIMIT","PRED_CONTEXT_RELATION"))if(!f.containsKey(k))throw invalid();if(!c.path("prediction").path("originDate").asText().equals(f.get("PRED_ORIGIN_DATE")))throw invalid();for(int i=1;i<=5;i++){LocalDate.parse(f.get("PRED_D"+i));if(!f.containsKey("PRED_P"+i))throw invalid();}}
 f.put("QA_MA_DEF","移动平均线反映选定窗口内收盘价的平均水平；均线位置本身不是交易指令");f.put("QA_MACD_DEF","该指标用短期与长期指数移动平均的差及其信号线观察趋势，柱值按系统公式计算；单日位置不能确认交叉事件");f.put("QA_RSI_DEF","相对强弱指标根据近期平均涨幅与跌幅衡量强弱，常用区间仅帮助理解，不保证后续表现");
 var root=m.createObjectNode().put("sourceAnalysisId",id).put("sourceContextHash",sourceHash).put("sourceCreatedAt",saved.path("createdAt").asText()).put("question",QuestionInput.normalize(question)).put("promptVersion",PROMPT).put("knowledgeVersion",KNOWLEDGE).put("providerModel",model);root.set("sourceContext",c.deepCopy());root.set("facts",m.valueToTree(f));var sorted=canonical(root,m);String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(m.writeValueAsBytes(sorted)));return new Facts(Collections.unmodifiableMap(f),sorted,hash);
 }catch(BusinessException x){throw x;}catch(Exception x){throw invalid();}}
 static JsonNode canonical(JsonNode n,ObjectMapper m){if(n.isObject()){var o=m.createObjectNode();var keys=new TreeSet<String>();n.fieldNames().forEachRemaining(keys::add);keys.forEach(k->o.set(k,canonical(n.get(k),m)));return o;}if(n.isArray()){var a=m.createArrayNode();n.forEach(v->a.add(canonical(v,m)));return a;}return n.deepCopy();}
 static BusinessException invalid(){return new BusinessException("QUESTION_EVIDENCE_INVALID","所选分析依据不完整，暂不能回答",HttpStatus.UNPROCESSABLE_ENTITY);}
}
